// JT-ZERO v36: mechanical yaw reference vs FC ATTITUDE and accelerometer gravity.
// Operator sets physical positions using stand marks, SPACE confirms each position.
// FC yaw is measured only; it is never used to decide that a target was reached.
// Route: physical 0 -> +90 -> 0 -> -90 -> 0. Russian GUI.
#define JTZERO_V10_NO_MAIN
#include "live_mono_imu_integrator_v10.cpp"
#undef JTZERO_V10_NO_MAIN
#include <array>
#include <fstream>
#include <iomanip>

namespace jtzero_v36 {
constexpr const char* kCsv36="/home/vio/jtzero_live_mechanical_yaw_fc_accel_v36.csv";
constexpr const char* kWindow36="JT-ZERO: МЕХАНИЧЕСКИЙ YAW v36";
constexpr int kPhases36=5;
constexpr double kMechanical36[kPhases36]={0,90,0,-90,0};
constexpr const char* kNames36[kPhases36]={"0_start","+90_mech","0_mid","-90_mech","0_final"};
constexpr double kGyroStill36=.035,kAccNormTol36=.45;
constexpr int kStableSamples36=120,kCollectSamples36=500;

struct Att36{bool valid=false;double roll=0,pitch=0,yaw=0;};
struct Row36{int phase=0;uint64_t us=0;double mech=0,fc_roll=0,fc_pitch=0,fc_yaw=0,fc_yaw_rel=0;Eigen::Vector3d acc=Eigen::Vector3d::Zero(),gyro=Eigen::Vector3d::Zero();};
struct Stats36{int n=0;Eigen::Vector3d sa=Eigen::Vector3d::Zero();double sr=0,sp=0,sy=0,syr=0;void add(const Row36&r){++n;sa+=r.acc;sr+=r.fc_roll;sp+=r.fc_pitch;sy+=r.fc_yaw;syr+=r.fc_yaw_rel;}Eigen::Vector3d meanAcc()const{Eigen::Vector3d o=Eigen::Vector3d::Zero();if(n)o=sa/double(n);return o;}};
static double normDeg36(double x){while(x>180)x-=360;while(x<-180)x+=360;return x;}
static void accelTilt36(const Eigen::Vector3d&a,double&r,double&p){Eigen::Vector3d u=a.normalized();r=std::atan2(u.y(),u.z())*180.0/kPi;p=std::atan2(-u.x(),std::sqrt(u.y()*u.y()+u.z()*u.z()))*180.0/kPi;}
static void save36(const std::vector<Row36>&v){std::ofstream f(kCsv36);f<<std::fixed<<std::setprecision(9)<<"phase,phase_name,mechanical_yaw_deg,imu_us,fc_roll_deg,fc_pitch_deg,fc_yaw_deg,fc_yaw_rel_deg,ax,ay,az,gx,gy,gz\n";for(const auto&r:v)f<<r.phase<<','<<kNames36[r.phase]<<','<<r.mech<<','<<r.us<<','<<r.fc_roll<<','<<r.fc_pitch<<','<<r.fc_yaw<<','<<r.fc_yaw_rel<<','<<r.acc.x()<<','<<r.acc.y()<<','<<r.acc.z()<<','<<r.gyro.x()<<','<<r.gyro.y()<<','<<r.gyro.z()<<'\n';}
static void summary36(const std::array<Stats36,kPhases36>&s){std::cout<<std::fixed<<std::setprecision(9)<<"\n============================================================\nJT-ZERO MECHANICAL YAW v36 RESULT\n============================================================\n";double r0=s[0].sr/s[0].n,p0=s[0].sp/s[0].n,y0=s[0].syr/s[0].n,ar0=0,ap0=0;accelTilt36(s[0].meanAcc(),ar0,ap0);for(int i=0;i<kPhases36;i++){double r=s[i].sr/s[i].n,p=s[i].sp/s[i].n,yr=s[i].syr/s[i].n,ar=0,ap=0;Eigen::Vector3d a=s[i].meanAcc();accelTilt36(a,ar,ap);std::cout<<"\n"<<kNames36[i]<<" mechanical="<<kMechanical36[i]<<" deg n="<<s[i].n<<"\n FC R/P/Yrel=["<<r<<","<<p<<","<<yr<<"] deg\n ACC tilt R/P=["<<ar<<","<<ap<<"] deg\n mean accel=["<<a.transpose()<<"] |a|="<<a.norm()<<"\n FC yaw error vs mechanical="<<normDeg36(yr-kMechanical36[i])<<" deg\n delta FC tilt vs first 0=["<<r-r0<<","<<p-p0<<"] deg\n delta ACC tilt vs first 0=["<<ar-ar0<<","<<ap-ap0<<"] deg\n";}double rf=s[4].sr/s[4].n,pf=s[4].sp/s[4].n,yrf=s[4].syr/s[4].n,arf=0,apf=0;accelTilt36(s[4].meanAcc(),arf,apf);double fcTilt=std::hypot(rf-r0,pf-p0),accTilt=std::hypot(arf-ar0,apf-ap0);double eplus=normDeg36(s[1].syr/s[1].n-90.0),eminus=normDeg36(s[3].syr/s[3].n+90.0);std::cout<<"\nDecision helper:\n physical +90: FC yaw error="<<eplus<<" deg\n physical -90: FC yaw error="<<eminus<<" deg\n final physical 0: FC yaw return error="<<normDeg36(yrf-y0)<<" deg\n final physical 0: FC tilt delta="<<fcTilt<<" deg\n final physical 0: ACC tilt delta="<<accTilt<<" deg\n";if(accTilt<.3&&fcTilt>.8)std::cout<<" RESULT: mechanical/gravity return is good but FC tilt does not return. FC estimator/source semantics confirmed as primary diagnostic target.\n";else if(accTilt>.8)std::cout<<" RESULT: physical tilt did not repeat well enough; improve stand/mechanical repeatability before estimator conclusion.\n";else std::cout<<" RESULT: return is reasonably consistent; inspect signed FC yaw errors at mechanical +/-90 and per-phase tilt.\n";}
static void hud36(const Att36&a,const Eigen::Vector3d&acc,const Eigen::Vector3d&gyro,bool started,bool armed,bool done,int ph,int stable,int collected,double yawRel){cv::Mat c(850,1300,CV_8UC3,cv::Scalar(15,15,15));cv::Scalar w(235,235,235),gr(80,220,80),ye(0,220,255),red(80,80,255);uiText(c,"JT-ZERO: МЕХАНИЧЕСКИЙ YAW v36",30,52,.72,w,2);if(!started){uiText(c,"ПОСТАВЬТЕ СТЕНД В ФИЗИЧЕСКИЙ 0°",65,120,.65,ye,2);uiText(c,"SPACE — ПОДТВЕРДИТЬ ПЕРВЫЙ 0°",65,175,.56,w,2);}else if(done){uiText(c,"ТЕСТ ЗАВЕРШЁН",65,120,.82,gr,3);uiText(c,"SPACE — ВЫХОД",65,175,.52,w,2);}else if(!armed){char t[160];snprintf(t,sizeof(t),"ПОСТАВЬТЕ ПО РАЗМЕТКЕ: ФИЗИЧЕСКИЙ %+.0f°",kMechanical36[ph]);uiText(c,t,65,120,.64,ye,2);uiText(c,"НЕ ОРИЕНТИРУЙТЕСЬ ПО FC YAW. SPACE — ПОЛОЖЕНИЕ УСТАНОВЛЕНО",65,175,.50,red,2);}else{uiText(c,stable>=kStableSamples36?"СТОП! СТЕНД НЕ ДВИГАТЬ — ИДЁТ СБОР":"СТЕНД ЗАФИКСИРОВАН. ЖДУ НЕПОДВИЖНОСТЬ...",65,120,.58,stable>=kStableSamples36?gr:w,2);}cv::Mat q=c(cv::Rect(50,230,1200,550));double ar=0,ap=0;if(acc.norm()>1)accelTilt36(acc,ar,ap);char t[256];snprintf(t,sizeof(t),"МЕХАНИЧЕСКАЯ ЦЕЛЬ: %+.0f°",done?0:kMechanical36[ph]);uiText(q,t,20,65,.58,ye,2);snprintf(t,sizeof(t),"FC: R %+.2f°   P %+.2f°   YAW от старта %+.2f°",a.roll,a.pitch,yawRel);uiText(q,t,20,135,.48,w,1);snprintf(t,sizeof(t),"ACC gravity: R %+.2f°   P %+.2f°",ar,ap);uiText(q,t,20,190,.48,gr,1);snprintf(t,sizeof(t),"|gyro| %.4f rad/s   |acc| %.4f m/s²",gyro.norm(),acc.norm());uiText(q,t,20,245,.44,w,1);snprintf(t,sizeof(t),"Стабилизация %d/%d   Собрано %d/%d",stable,kStableSamples36,collected,kCollectSamples36);uiText(q,t,20,300,.44,w,1);uiText(q,"Маршрут по механической разметке: 0 → +90 → 0 → -90 → 0",20,440,.45,w,1);cv::imshow(kWindow36,c);}
}

int main(int argc,char**argv){google::InitGoogleLogging(argv[0]);int fd=-1;uint8_t sys=0,comp=0;mavlink_status_t mst{};mavlink_message_t msg{};bool started=false,armed=false,done=false;int ph=0,stable=0,collected=0;double yawRef=0;jtzero_v36::Att36 at;Eigen::Vector3d acc=Eigen::Vector3d::Zero(),gyro=Eigen::Vector3d::Zero();std::array<jtzero_v36::Stats36,jtzero_v36::kPhases36> stats;std::vector<jtzero_v36::Row36> rows;uint64_t last=0;try{fd=openSerial();std::cout<<"[MAV] waiting for HEARTBEAT...\n";int64_t dl=monotonicNs()+10000000000LL;while(monotonicNs()<dl&&!sys){pollfd p{fd,POLLIN,0};if(poll(&p,1,100)<=0)continue;uint8_t b[2048];ssize_t n=read(fd,b,sizeof(b));if(n<=0)continue;for(ssize_t i=0;i<n;i++)if(mavlink_parse_char(MAVLINK_COMM_0,b[i],&msg,&mst)&&msg.msgid==MAVLINK_MSG_ID_HEARTBEAT){sys=msg.sysid;comp=msg.compid;break;}}if(!sys)throw std::runtime_error("HEARTBEAT timeout");requestRate(fd,sys,comp,MAVLINK_MSG_ID_ATTITUDE,100);requestRate(fd,sys,comp,MAVLINK_MSG_ID_HIGHRES_IMU,200);cv::namedWindow(jtzero_v36::kWindow36);int64_t nh=0;while(true){pollfd p{fd,POLLIN,0};poll(&p,1,5);if(p.revents&POLLIN){uint8_t b[8192];ssize_t n=read(fd,b,sizeof(b));if(n>0)for(ssize_t i=0;i<n;i++)if(mavlink_parse_char(MAVLINK_COMM_0,b[i],&msg,&mst)){if(msg.msgid==MAVLINK_MSG_ID_ATTITUDE){mavlink_attitude_t a{};mavlink_msg_attitude_decode(&msg,&a);at.valid=true;at.roll=a.roll*180/kPi;at.pitch=a.pitch*180/kPi;at.yaw=a.yaw*180/kPi;}else if(msg.msgid==MAVLINK_MSG_ID_HIGHRES_IMU){mavlink_highres_imu_t h{};mavlink_msg_highres_imu_decode(&msg,&h);if(h.time_usec==last)continue;last=h.time_usec;acc={h.xacc,-h.yacc,-h.zacc};gyro={h.xgyro,-h.ygyro,-h.zgyro};if(started&&armed&&!done&&at.valid){bool still=gyro.norm()<=jtzero_v36::kGyroStill36&&std::abs(acc.norm()-9.81)<=jtzero_v36::kAccNormTol36;if(still){if(stable<jtzero_v36::kStableSamples36)stable++;else{jtzero_v36::Row36 r;r.phase=ph;r.us=h.time_usec;r.mech=jtzero_v36::kMechanical36[ph];r.fc_roll=at.roll;r.fc_pitch=at.pitch;r.fc_yaw=at.yaw;r.fc_yaw_rel=jtzero_v36::normDeg36(at.yaw-yawRef);r.acc=acc;r.gyro=gyro;rows.push_back(r);stats[ph].add(r);if(++collected>=jtzero_v36::kCollectSamples36){std::cout<<"[STEP] "<<jtzero_v36::kNames36[ph]<<" collected.\n";stable=collected=0;armed=false;if(++ph>=jtzero_v36::kPhases36){ph=4;done=true;std::cout<<"[TEST] completed.\n";}else std::cout<<"[NEXT] set mechanical "<<jtzero_v36::kMechanical36[ph]<<" deg and press SPACE.\n";}}}else stable=0;}}}}if(monotonicNs()>=nh){double yr=started&&at.valid?jtzero_v36::normDeg36(at.yaw-yawRef):0;jtzero_v36::hud36(at,acc,gyro,started,armed,done,ph,stable,collected,yr);nh=monotonicNs()+33333333LL;}int k=cv::waitKey(1)&255;if(k==27||k=='q'||k=='Q')break;if(k==' '&&!started&&at.valid){yawRef=at.yaw;started=true;armed=true;ph=0;stable=collected=0;std::cout<<"[ZERO] physical 0 confirmed; FC yaw reference fixed.\n";}else if(k==' '&&started&&!done&&!armed){armed=true;stable=collected=0;std::cout<<"[CONFIRM] mechanical "<<jtzero_v36::kMechanical36[ph]<<" deg confirmed; waiting for stillness.\n";}else if(k==' '&&done)break;}jtzero_v36::save36(rows);jtzero_v36::summary36(stats);std::cout<<"\nCSV: "<<jtzero_v36::kCsv36<<"\nOpen CSV:\n  code "<<jtzero_v36::kCsv36<<"\n";requestRate(fd,sys,comp,MAVLINK_MSG_ID_ATTITUDE,0);requestRate(fd,sys,comp,MAVLINK_MSG_ID_HIGHRES_IMU,0);close(fd);cv::destroyAllWindows();return 0;}catch(const std::exception&e){if(fd>=0)close(fd);cv::destroyAllWindows();std::cerr<<"[FATAL] "<<e.what()<<"\n";return 1;}}
